// Розкладаємо задачі на два зрізи: цей тиждень і попередній.
// Без попереднього зрізу агент не зможе порівняти обіцяне зі зробленим.
const cfg = $('Config1').first().json;

// Нода ClickUp (getAll) віддає КОЖНУ задачу окремим item.
// HTTP Request віддає всі задачі масивом у полі tasks першого item.
// Підтримуємо обидва варіанти.
const items = $input.all().map((i) => i.json);
const tasks = items.length === 1 && Array.isArray(items[0].tasks) ? items[0].tasks : items;

const num = (v) => (v === null || v === undefined || v === '' ? null : Number(v));
const day = (v) => (num(v) ? new Date(num(v)).toISOString().slice(0, 10) : null);
const hrs = (v) => (num(v) ? +(num(v) / 3600000).toFixed(1) : null);

const slim = tasks.map((t) => ({
  id: t.id,
  name: t.name,
  status: t.status?.status ?? null,
  closed: t.status?.type === 'closed',
  assignees: (t.assignees || []).map((a) => a.username || a.email).filter(Boolean),
  tags: (t.tags || []).map((x) => x.name),
  description: (t.description || t.text_content || '').slice(0, 400),
  due_date: day(t.due_date),
  date_closed: day(t.date_closed),
  time_estimate_h: hrs(t.time_estimate),
  time_spent_h: hrs(t.time_spent),
  over_estimate_h:
    hrs(t.time_spent) && hrs(t.time_estimate)
      ? +(hrs(t.time_spent) - hrs(t.time_estimate)).toFixed(1)
      : null,
  priority: t.priority?.priority ?? null,
  _anchor: num(t.date_closed) ?? num(t.due_date),
}));

// Зріз визначаємо за ДАТОЮ ЗАДАЧІ (закриття або дедлайн), а не за date_updated:
// date_updated міняється щоразу, коли хтось торкнувся задачі, і всі задачі
// злипаються в поточний тиждень.
const since = Number(cfg.since_ms);
const isCurrent = (t) => t._anchor === null || t._anchor >= since;

const strip = (t) => { const { _anchor, ...rest } = t; return rest; };
const current = slim.filter(isCurrent).map(strip);
const previous = slim.filter((t) => !isCurrent(t)).map(strip);

return [{
  json: {
    project_name: cfg.project_name,
    milestone: cfg.milestone,
    client_email: cfg.client_email,
    pm_chat_id: cfg.pm_chat_id,
    period_from: new Date(since).toISOString().slice(0, 10),
    period_to: new Date().toISOString().slice(0, 10),
    current_week: current,
    previous_week: previous,
    counts: {
      total: slim.length,
      closed_this_week: current.filter((t) => t.closed).length,
      open_now: slim.filter((t) => !t.closed).length,
    },
    comparison_available: previous.length > 0,
  },
}];

